SELECT fn_cp_import_case('conflits-personne-alcoolisee-sur-voie-publique', '{"slug": "conflits-personne-alcoolisee-sur-voie-publique", "title": "Il chante fort et interpelle les passants sans agressivité", "theme_slug": "gestion-conflits", "difficulty": "facile", "is_free": true, "is_published": true, "status": "published", "year": 2026, "month": "Juillet", "total_points": 15, "estimated_minutes": 20, "situation_text": "Il est 23 heures. Dans une rue piétonne, un homme visiblement alcoolisé chante fort et interpelle les passants sans toutefois manifester la moindre agressivité, ce trouble restant modéré dans son intensité alors même que cette personne se trouve dans un état de vulnérabilité de fait qui mérite une attention particulière au-delà du seul trouble constaté sur cette voie publique. Cette configuration, où cette alcoolisation sans violence pose un double enjeu de gestion du trouble et de protection de cette personne fragilisée, nécessite de traiter cette vulnérabilité avec autant d''attention que le trouble lui-même occasionné sur cette voie publique.\n\nCette situation, caractéristique des interventions nocturnes où l''alcoolisation d''une personne crée un trouble mineur tout en révélant une fragilité réelle qui appelle une réponse protectrice, impose une approche qui ne se limite pas au seul rétablissement de l''ordre public.\n\nCette configuration nécessite de traiter la vulnérabilité de cette personne autant que le trouble qu''elle occasionne, cette double exigence restant essentielle pour une gestion complète et humaine de cette situation nocturne.", "questions": [{"position": 1, "max_points": 5, "label": "Comment traitez-vous la vulnérabilité de cette personne autant que le trouble qu''elle occasionne ?", "hint": "Cette vulnérabilité mérite une attention aussi importante que la gestion du trouble lui-même, cette personne restant fragilisée par son état d''alcoolisation sur cette voie publique.", "perfect": "Je reste attentive à l''état d''alcoolisation de cette personne, cette vulnérabilité de fait méritant une attention protectrice au-delà du seul trouble qu''elle occasionne.\n\nJe reste factuelle et bienveillante dans mon approche, cette attitude restant appropriée pour ne pas aggraver sa situation déjà fragile par une intervention trop rigide.\n\nJe m''assure qu''elle ne présente pas de risque immédiat pour sa propre sécurité, notamment en évaluant son état de conscience et sa capacité à se déplacer en sécurité.\n\nJe reste attentive à la possibilité de la mettre en sécurité, notamment en la raccompagnant ou en sollicitant l''intervention de proches si cela s''avère nécessaire.", "points": [{"position": 1, "label": "Rester attentive à l''état d''alcoolisation et à cette vulnérabilité de fait", "weight": 2.0, "is_required": true, "kind": "core", "explanation_md": "Cœur du cas : attention protectrice au-delà du trouble.", "groups": [{"position": 1, "keywords": ["vulnérabilité reconnue", "attention protectrice", "alcoolisation observée"]}]}, {"position": 2, "label": "Rester factuelle et bienveillante dans son approche", "weight": 1.5, "is_required": true, "kind": "core", "explanation_md": "Attitude évitant d''aggraver une situation fragile.", "groups": [{"position": 1, "keywords": ["approche bienveillante", "situation fragile", "intervention adaptée"]}]}, {"position": 3, "label": "S''assurer qu''elle ne présente pas de risque pour sa propre sécurité", "weight": 1.0, "is_required": true, "kind": "core", "explanation_md": "Évaluation de son état de conscience et de sa capacité.", "groups": [{"position": 1, "keywords": ["risque évalué", "état de conscience", "sécurité personnelle"]}]}, {"position": 4, "label": "Rester attentive à la possibilité de la mettre en sécurité", "weight": 0.5, "is_required": false, "kind": "bonus", "explanation_md": "Raccompagnement ou sollicitation de proches si nécessaire.", "groups": [{"position": 1, "keywords": ["mise en sécurité", "raccompagnement envisagé", "proches sollicités"]}]}]}, {"position": 2, "max_points": 5, "label": "Comment gérez-vous ce trouble modéré sans disproportion face à cette absence d''agressivité ?", "hint": "Cette gestion doit rester proportionnée à un trouble qui reste modéré et non agressif, cette mesure restant appropriée face à cette absence de danger immédiat pour les tiers.", "perfect": "Je reste attentive à la proportionnalité de toute mesure envisagée, ce trouble restant modéré et non agressif dans son expression envers les passants présents.\n\nJe demande calmement à cette personne de modérer son comportement, cette demande restant appropriée face à ce trouble qui gêne sans pour autant présenter de danger réel.\n\nJe reste attentive à ne pas recourir à une mesure disproportionnée pour ce trouble mineur, cette retenue restant essentielle compte tenu de l''absence d''agressivité constatée.\n\nJe reste factuelle sur les conséquences possibles si ce trouble venait à persister, cette information restant utile sans pour autant constituer une menace disproportionnée.", "points": [{"position": 1, "label": "Rester attentive à la proportionnalité de toute mesure envisagée", "weight": 2.0, "is_required": true, "kind": "core", "explanation_md": "Cœur du cas : trouble modéré et non agressif.", "groups": [{"position": 1, "keywords": ["proportionnalité respectée", "trouble modéré", "absence d''agressivité"]}]}, {"position": 2, "label": "Demander calmement à cette personne de modérer son comportement", "weight": 1.5, "is_required": true, "kind": "core", "explanation_md": "Demande appropriée face à l''absence de danger réel.", "groups": [{"position": 1, "keywords": ["demande calme", "comportement modéré", "danger absent"]}]}, {"position": 3, "label": "Ne pas recourir à une mesure disproportionnée pour ce trouble mineur", "weight": 1.0, "is_required": true, "kind": "core", "explanation_md": "Retenue compte tenu de l''absence d''agressivité.", "groups": [{"position": 1, "keywords": ["retenue appliquée", "mesure proportionnée", "trouble mineur"]}]}, {"position": 4, "label": "Rester factuelle sur les conséquences possibles sans menace disproportionnée", "weight": 0.5, "is_required": false, "kind": "bonus", "explanation_md": "Information utile sans excès.", "groups": [{"position": 1, "keywords": ["conséquences expliquées", "menace évitée", "information factuelle"]}]}]}, {"position": 3, "max_points": 5, "label": "Comment gérez-vous les passants qui pourraient être interpellés par cette personne ?", "hint": "Ces passants méritent une attention particulière pour évaluer si cette interpellation crée une gêne réelle ou reste anodine dans le contexte de cette rue piétonne nocturne.", "perfect": "Je reste attentive à la réaction des passants interpellés par cette personne, cette observation restant utile pour évaluer l''ampleur réelle de ce trouble constaté.\n\nJe reste factuelle avec ces passants si certains expriment une gêne particulière, cette information leur permettant de comprendre la gestion en cours de cette situation.\n\nJe reste attentive à ne pas créer d''attroupement supplémentaire autour de cette personne déjà vulnérable, cette vigilance restant utile pour ne pas aggraver son exposition.\n\nJe reste disponible pour rassurer les passants les plus inquiets, cette disponibilité restant appropriée pour clore cette intervention sereinement.", "points": [{"position": 1, "label": "Rester attentive à la réaction des passants interpellés", "weight": 2.0, "is_required": true, "kind": "core", "explanation_md": "Cœur du cas : évaluation de l''ampleur réelle du trouble.", "groups": [{"position": 1, "keywords": ["réaction observée", "ampleur évaluée", "trouble constaté"]}]}, {"position": 2, "label": "Rester factuelle avec les passants exprimant une gêne particulière", "weight": 1.5, "is_required": true, "kind": "core", "explanation_md": "Information sur la gestion en cours.", "groups": [{"position": 1, "keywords": ["passants informés", "gêne exprimée", "gestion expliquée"]}]}, {"position": 3, "label": "Ne pas créer d''attroupement supplémentaire autour de cette personne vulnérable", "weight": 1.0, "is_required": true, "kind": "core", "explanation_md": "Vigilance limitant l''exposition de cette personne.", "groups": [{"position": 1, "keywords": ["attroupement évité", "exposition limitée", "personne vulnérable"]}]}, {"position": 4, "label": "Rester disponible pour rassurer les passants les plus inquiets", "weight": 0.5, "is_required": false, "kind": "bonus", "explanation_md": "Disponibilité concluant sereinement l''intervention.", "groups": [{"position": 1, "keywords": ["passants rassurés", "disponibilité maintenue", "intervention sereine"]}]}]}]}'::jsonb);
SELECT fn_cp_import_case('conflits-accusation-de-discrimination-pendant-controle', '{"slug": "conflits-accusation-de-discrimination-pendant-controle", "title": "Il vous demande pourquoi lui et pas les autres", "theme_slug": "gestion-conflits", "difficulty": "difficile", "is_free": false, "is_published": true, "status": "published", "year": 2026, "month": "Juillet", "total_points": 15, "estimated_minutes": 30, "situation_text": "Il est 17 heures. Lors d''un contrôle sur la voie publique, la personne contrôlée vous demande directement pourquoi vous l''avez contrôlée elle et pas les autres personnes présentes à ses côtés, cette question restant légitime dans sa formulation et nécessitant une réponse construite qui évite toute agressivité tout en préservant la crédibilité de votre action face à cette interrogation directe. Cette configuration, où cette contestation du motif de ce contrôle s''inscrit dans un contexte plus large de sensibilité aux discriminations perçues lors des contrôles d''identité, nécessite d''expliquer calmement le motif réel de ce contrôle sans céder à une réaction défensive qui aggraverait cette situation.\n\nCette situation, caractéristique des contrôles où la personne interrogée s''interroge légitimement sur les critères ayant présidé au choix de son contrôle plutôt que celui d''autres personnes présentes, impose une transparence appropriée sur ce motif tout en restant factuelle sur le cadre légal de cette action.\n\nCette configuration nécessite d''expliquer calmement le motif du contrôle sans agressivité, cette pédagogie restant essentielle pour désamorcer cette question légitime sans pour autant remettre en cause la légitimité de votre action initiale.", "questions": [{"position": 1, "max_points": 5, "label": "Comment expliquez-vous calmement le motif de ce contrôle sans agressivité face à cette question ?", "hint": "Cette explication doit rester calme et factuelle, cette question méritant une réponse construite plutôt qu''une réaction défensive qui aggraverait cette situation.", "perfect": "J''explique calmement le motif concret qui a présidé à ce contrôle, cette transparence restant appropriée face à cette question qui reste légitime dans sa formulation.\n\nJe reste factuelle sur le cadre légal qui encadre ce type de contrôle, cette explication restant utile pour clarifier les critères objectifs ayant guidé mon action.\n\nJe reste attentive à ne pas réagir avec agressivité à cette question, cette maîtrise restant essentielle pour ne pas transformer cette interrogation légitime en confrontation.\n\nJe reste attentive à la manière dont cette explication est reçue, cette écoute restant utile pour adapter si nécessaire la suite de mes échanges avec cette personne.", "points": [{"position": 1, "label": "Expliquer calmement le motif concret ayant présidé à ce contrôle", "weight": 2.0, "is_required": true, "kind": "core", "explanation_md": "Cœur du cas : transparence appropriée face à une question légitime.", "groups": [{"position": 1, "keywords": ["motif expliqué", "transparence appliquée", "question légitime"]}]}, {"position": 2, "label": "Rester factuelle sur le cadre légal encadrant ce contrôle", "weight": 1.5, "is_required": true, "kind": "core", "explanation_md": "Clarification des critères objectifs.", "groups": [{"position": 1, "keywords": ["cadre légal précisé", "critères objectifs", "explication factuelle"]}]}, {"position": 3, "label": "Ne pas réagir avec agressivité à cette question", "weight": 1.0, "is_required": true, "kind": "core", "explanation_md": "Maîtrise évitant une confrontation.", "groups": [{"position": 1, "keywords": ["agressivité évitée", "maîtrise maintenue", "confrontation évitée"]}]}, {"position": 4, "label": "Rester attentive à la manière dont cette explication est reçue", "weight": 0.5, "is_required": false, "kind": "bonus", "explanation_md": "Écoute adaptant la suite des échanges.", "groups": [{"position": 1, "keywords": ["réception observée", "échanges adaptés", "écoute maintenue"]}]}]}, {"position": 2, "max_points": 5, "label": "Comment préservez-vous la crédibilité de votre action face à cette contestation du motif de ce contrôle ?", "hint": "Cette crédibilité doit être préservée sans pour autant paraître sur la défensive, cette contestation méritant une réponse assurée mais respectueuse de la légitimité de cette question.", "perfect": "Je reste assurée dans mes explications sans pour autant paraître sur la défensive, cette posture restant appropriée face à cette contestation qui reste mesurée dans son expression.\n\nJe reste attentive à ne pas me justifier de manière excessive, cette mesure restant appropriée pour préserver ma crédibilité sans donner l''impression de me sentir prise en faute.\n\nJe reste factuelle sur les critères objectifs de mon action, cette rigueur restant essentielle pour démontrer le caractère non arbitraire de ce contrôle effectué.\n\nJe reste attentive à conclure cet échange de manière professionnelle, cette sérénité restant importante pour clore positivement cette interaction malgré cette contestation initiale.", "points": [{"position": 1, "label": "Rester assurée sans paraître sur la défensive", "weight": 2.0, "is_required": true, "kind": "core", "explanation_md": "Cœur du cas : posture appropriée face à une contestation mesurée.", "groups": [{"position": 1, "keywords": ["assurance maintenue", "défensive évitée", "posture appropriée"]}]}, {"position": 2, "label": "Ne pas se justifier de manière excessive", "weight": 1.5, "is_required": true, "kind": "core", "explanation_md": "Mesure préservant la crédibilité.", "groups": [{"position": 1, "keywords": ["justification mesurée", "crédibilité préservée", "excès évité"]}]}, {"position": 3, "label": "Rester factuelle sur les critères objectifs de son action", "weight": 1.0, "is_required": true, "kind": "core", "explanation_md": "Rigueur démontrant le caractère non arbitraire.", "groups": [{"position": 1, "keywords": ["critères objectifs", "action non arbitraire", "rigueur maintenue"]}]}, {"position": 4, "label": "Conclure cet échange de manière professionnelle et sereine", "weight": 0.5, "is_required": false, "kind": "bonus", "explanation_md": "Sérénité clôturant positivement l''interaction.", "groups": [{"position": 1, "keywords": ["conclusion sereine", "interaction positive", "professionnalisme maintenu"]}]}]}, {"position": 3, "max_points": 5, "label": "Comment rendez-vous compte de cette interaction à votre hiérarchie une fois ce contrôle terminé ?", "hint": "Ce compte rendu doit permettre de documenter cette contestation et la manière dont elle a été gérée, cette information restant utile compte tenu de la sensibilité de ce type de situation.", "perfect": "Je transmets à ma hiérarchie l''existence de cette contestation du motif de ce contrôle, cette information restant utile compte tenu de la sensibilité de ce type d''interaction.\n\nJe reste factuelle sur les critères objectifs qui ont guidé mon action initiale, cette information permettant d''apprécier le caractère justifié de ce contrôle effectué.\n\nJe reste attentive à documenter la manière dont j''ai géré cette contestation, cette traçabilité restant utile pour une éventuelle suite à cette interaction.\n\nJe reste disponible pour toute précision complémentaire, cette réactivité restant importante compte tenu de la sensibilité particulière de ce type de situation vécue.", "points": [{"position": 1, "label": "Transmettre l''existence de cette contestation à la hiérarchie", "weight": 2.0, "is_required": true, "kind": "core", "explanation_md": "Cœur du cas : information utile compte tenu de la sensibilité.", "groups": [{"position": 1, "keywords": ["contestation transmise", "hiérarchie informée", "sensibilité reconnue"]}]}, {"position": 2, "label": "Rester factuelle sur les critères objectifs ayant guidé l''action", "weight": 1.5, "is_required": true, "kind": "core", "explanation_md": "Information appréciant le caractère justifié du contrôle.", "groups": [{"position": 1, "keywords": ["critères objectifs", "action justifiée", "information factuelle"]}]}, {"position": 3, "label": "Documenter la manière dont cette contestation a été gérée", "weight": 1.0, "is_required": true, "kind": "core", "explanation_md": "Traçabilité utile pour une éventuelle suite.", "groups": [{"position": 1, "keywords": ["gestion documentée", "traçabilité assurée", "suite éventuelle"]}]}, {"position": 4, "label": "Rester disponible pour toute précision complémentaire", "weight": 0.5, "is_required": false, "kind": "bonus", "explanation_md": "Réactivité compte tenu de la sensibilité de la situation.", "groups": [{"position": 1, "keywords": ["disponibilité maintenue", "précision complémentaire", "sensibilité particulière"]}]}]}]}'::jsonb);
SELECT fn_cp_import_case('conflits-personne-filme-l-intervention-de-pres', '{"slug": "conflits-personne-filme-l-intervention-de-pres", "title": "Il approche son téléphone à trente centimètres de votre visage", "theme_slug": "gestion-conflits", "difficulty": "moyen", "is_free": true, "is_published": true, "status": "published", "year": 2026, "month": "Juillet", "total_points": 15, "estimated_minutes": 25, "situation_text": "Il est 19 heures. Lors de votre intervention sur une rue, une personne filme votre action en approchant son téléphone à une trentaine de centimètres de votre visage, cette captation restant licite dans son principe mais cette proximité physique gênant concrètement le déroulement normal de votre action sur cette voie publique. Cette configuration, où cette captation vidéo demeure un droit reconnu qui ne peut être interdit en tant que tel, nécessite de distinguer clairement la question de la distance physique gênante de celle du droit de filmer qui reste par principe protégé dans ce contexte d''intervention publique.\n\nCette situation, caractéristique des interventions filmées à proximité immédiate qui peuvent perturber matériellement l''action des forces de l''ordre sans pour autant justifier une interdiction de cette captation, impose de demander une distance appropriée sans jamais interdire cette pratique de filmage elle-même.\n\nCette configuration nécessite de demander une distance sans interdire cette captation licite, cette distinction restant essentielle pour concilier le respect de ce droit avec les nécessités pratiques de votre intervention en cours.", "questions": [{"position": 1, "max_points": 5, "label": "Comment demandez-vous une distance appropriée sans interdire cette captation licite ?", "hint": "Cette demande doit porter exclusivement sur la distance physique gênante, cette distinction restant essentielle pour ne pas interdire une pratique de filmage qui reste par principe licite.", "perfect": "Je demande clairement à cette personne de reculer d''une distance appropriée, cette demande portant exclusivement sur la proximité physique gênante et non sur son droit de filmer.\n\nJe reste attentive à ne jamais formuler cette demande comme une interdiction de filmer, cette distinction restant essentielle pour respecter ce droit qui demeure protégé dans ce contexte.\n\nJe reste factuelle sur les raisons pratiques de cette demande de distance, cette explication restant utile pour qu''elle comprenne la nature réelle de ma sollicitation.\n\nJe reste attentive à la réaction de cette personne face à cette demande, cette observation restant utile pour adapter si nécessaire la suite de mon intervention.", "points": [{"position": 1, "label": "Demander clairement à reculer d''une distance appropriée", "weight": 2.0, "is_required": true, "kind": "core", "explanation_md": "Cœur du cas : demande portant sur la distance, non sur le droit de filmer.", "groups": [{"position": 1, "keywords": ["distance demandée", "proximité gênante", "droit préservé"]}]}, {"position": 2, "label": "Ne jamais formuler cette demande comme une interdiction de filmer", "weight": 1.5, "is_required": true, "kind": "core", "explanation_md": "Distinction essentielle pour respecter ce droit protégé.", "groups": [{"position": 1, "keywords": ["interdiction évitée", "droit respecté", "distinction maintenue"]}]}, {"position": 3, "label": "Rester factuelle sur les raisons pratiques de cette demande", "weight": 1.0, "is_required": true, "kind": "core", "explanation_md": "Explication utile sur la nature réelle de la sollicitation.", "groups": [{"position": 1, "keywords": ["raisons expliquées", "sollicitation clarifiée", "explication factuelle"]}]}, {"position": 4, "label": "Rester attentive à la réaction de cette personne face à cette demande", "weight": 0.5, "is_required": false, "kind": "bonus", "explanation_md": "Observation adaptant la suite de l''intervention.", "groups": [{"position": 1, "keywords": ["réaction observée", "intervention adaptée", "suite ajustée"]}]}]}, {"position": 2, "max_points": 5, "label": "Comment poursuivez-vous votre intervention principale malgré cette perturbation liée à cette proximité de captation ?", "hint": "Cette intervention principale doit se poursuivre normalement malgré cette perturbation, cette gestion de la captation restant distincte de l''action à mener sur le fond de cette situation.", "perfect": "Je reste concentrée sur mon intervention principale malgré cette proximité gênante, cette priorité restant claire indépendamment de cette perturbation liée à cette captation.\n\nJe reste attentive à ne pas me laisser distraire par la présence de cette caméra, cette maîtrise restant essentielle pour maintenir la qualité de mon action en cours.\n\nJe reste factuelle et professionnelle dans l''ensemble de mes gestes, cette rigueur restant appropriée compte tenu de cette exposition potentielle de mon intervention.\n\nJe reste attentive à poursuivre normalement cette intervention une fois la distance appropriée obtenue, cette continuité restant essentielle pour ne pas prolonger inutilement cette perturbation.", "points": [{"position": 1, "label": "Rester concentrée sur son intervention principale malgré cette proximité", "weight": 2.0, "is_required": true, "kind": "core", "explanation_md": "Cœur du cas : priorité maintenue malgré la perturbation.", "groups": [{"position": 1, "keywords": ["concentration maintenue", "intervention prioritaire", "perturbation gérée"]}]}, {"position": 2, "label": "Ne pas se laisser distraire par la présence de cette caméra", "weight": 1.5, "is_required": true, "kind": "core", "explanation_md": "Maîtrise préservant la qualité de l''action.", "groups": [{"position": 1, "keywords": ["distraction évitée", "maîtrise maintenue", "qualité préservée"]}]}, {"position": 3, "label": "Rester factuelle et professionnelle dans l''ensemble de ses gestes", "weight": 1.0, "is_required": true, "kind": "core", "explanation_md": "Rigueur compte tenu de cette exposition potentielle.", "groups": [{"position": 1, "keywords": ["gestes professionnels", "rigueur maintenue", "exposition potentielle"]}]}, {"position": 4, "label": "Poursuivre normalement l''intervention une fois la distance obtenue", "weight": 0.5, "is_required": false, "kind": "bonus", "explanation_md": "Continuité évitant de prolonger la perturbation.", "groups": [{"position": 1, "keywords": ["intervention poursuivie", "continuité assurée", "perturbation limitée"]}]}]}, {"position": 3, "max_points": 5, "label": "Comment rendez-vous compte de cette captation à votre hiérarchie une fois cette intervention terminée ?", "hint": "Ce compte rendu doit permettre de documenter cette captation et la manière dont vous l''avez gérée, cette information restant utile compte tenu de la diffusion possible de ces images.", "perfect": "Je transmets à ma hiérarchie l''existence de cette captation à proximité immédiate, cette information restant utile compte tenu de la diffusion possible de ces images ultérieurement.\n\nJe reste factuelle sur la manière dont j''ai géré cette situation, notamment ma demande de distance sans jamais interdire cette pratique de filmage.\n\nJe reste attentive à documenter le déroulement de mon intervention principale, cette traçabilité restant utile en cas de contestation ultérieure sur la base de cette vidéo.\n\nJe reste disponible pour toute précision complémentaire, cette réactivité restant importante si cette vidéo venait à faire l''objet d''une diffusion ou d''un signalement.", "points": [{"position": 1, "label": "Transmettre l''existence de cette captation à proximité immédiate", "weight": 2.0, "is_required": true, "kind": "core", "explanation_md": "Cœur du cas : information utile compte tenu de la diffusion possible.", "groups": [{"position": 1, "keywords": ["captation transmise", "diffusion possible", "hiérarchie informée"]}]}, {"position": 2, "label": "Rester factuelle sur la manière dont la situation a été gérée", "weight": 1.5, "is_required": true, "kind": "core", "explanation_md": "Gestion sans interdiction du filmage rapportée.", "groups": [{"position": 1, "keywords": ["gestion rapportée", "distance demandée", "filmage non interdit"]}]}, {"position": 3, "label": "Documenter le déroulement de l''intervention principale", "weight": 1.0, "is_required": true, "kind": "core", "explanation_md": "Traçabilité utile en cas de contestation.", "groups": [{"position": 1, "keywords": ["déroulement documenté", "traçabilité assurée", "contestation anticipée"]}]}, {"position": 4, "label": "Rester disponible pour toute précision complémentaire", "weight": 0.5, "is_required": false, "kind": "bonus", "explanation_md": "Réactivité en cas de diffusion ou signalement.", "groups": [{"position": 1, "keywords": ["disponibilité maintenue", "diffusion éventuelle", "signalement possible"]}]}]}]}'::jsonb);
SELECT fn_cp_import_case('conflits-insultes-envers-les-agents', '{"slug": "conflits-insultes-envers-les-agents", "title": "Les insultes fusent depuis un balcon, plusieurs personnes rient", "theme_slug": "gestion-conflits", "difficulty": "moyen", "is_free": false, "is_published": true, "status": "published", "year": 2026, "month": "Juillet", "total_points": 15, "estimated_minutes": 25, "situation_text": "Il est 22 heures. Alors que vous intervenez sur la voie publique, des insultes fusent depuis un balcon situé au-dessus de vous, plusieurs personnes présentes riant ouvertement de cette situation qui touche directement votre équipage sans qu''aucun contact direct ne soit possible avec cette personne qui reste à distance et hors de portée immédiate de votre intervention. Cette configuration, où cette atteinte personnelle ressentie s''accompagne d''un public qui observe et parfois s''amuse de cette situation, nécessite de ne pas réagir sous le coup de l''émotion malgré la charge affective que représente cet outrage à distance.\n\nCette situation, caractéristique des atteintes verbales qui touchent personnellement les agents sans qu''un contact direct immédiat ne soit possible avec l''auteur de ces propos, impose une maîtrise émotionnelle qui ne cède pas à la tentation d''une réaction disproportionnée face à ce public qui observe.\n\nCette configuration nécessite de ne pas réagir sous le coup de l''émotion face à ces insultes, cette maîtrise restant essentielle pour préserver votre professionnalisme malgré cette provocation qui vous touche personnellement.", "questions": [{"position": 1, "max_points": 5, "label": "Comment ne réagissez-vous pas sous le coup de l''émotion face à ces insultes qui vous touchent personnellement ?", "hint": "Cette maîtrise émotionnelle doit primer malgré la charge affective de cet outrage, cette retenue restant essentielle pour préserver votre professionnalisme face à ce public qui observe.", "perfect": "Je reste consciente que ces insultes, bien que touchant personnellement mon équipage, ne doivent pas conduire à une réaction disproportionnée de ma part.\n\nJe maintiens mon calme malgré cette provocation directe, cette maîtrise restant essentielle pour préserver mon professionnalisme face à ce public qui observe cette situation.\n\nJe reste attentive à ne pas prendre à partie ce public qui rit de cette situation, cette retenue restant appropriée pour ne pas élargir inutilement cet incident.\n\nJe reste concentrée sur ma mission initiale malgré cette perturbation, cette priorité restant claire indépendamment de cette atteinte verbale reçue depuis ce balcon.", "points": [{"position": 1, "label": "Rester consciente que ces insultes ne doivent pas conduire à une réaction disproportionnée", "weight": 2.0, "is_required": true, "kind": "core", "explanation_md": "Cœur du cas : maîtrise face à une atteinte personnelle.", "groups": [{"position": 1, "keywords": ["réaction proportionnée", "insultes reçues", "maîtrise maintenue"]}]}, {"position": 2, "label": "Maintenir son calme malgré cette provocation directe", "weight": 1.5, "is_required": true, "kind": "core", "explanation_md": "Professionnalisme préservé face au public.", "groups": [{"position": 1, "keywords": ["calme maintenu", "professionnalisme préservé", "public présent"]}]}, {"position": 3, "label": "Ne pas prendre à partie le public qui rit de cette situation", "weight": 1.0, "is_required": true, "kind": "core", "explanation_md": "Retenue évitant d''élargir l''incident.", "groups": [{"position": 1, "keywords": ["public non pris à partie", "incident non élargi", "retenue appliquée"]}]}, {"position": 4, "label": "Rester concentrée sur sa mission initiale malgré cette perturbation", "weight": 0.5, "is_required": false, "kind": "bonus", "explanation_md": "Priorité claire indépendamment de cette atteinte.", "groups": [{"position": 1, "keywords": ["mission prioritaire", "concentration maintenue", "atteinte reçue"]}]}]}, {"position": 2, "max_points": 5, "label": "Comment gérez-vous l''impossibilité de contact direct avec l''auteur de ces insultes depuis ce balcon ?", "hint": "Cette impossibilité de contact direct nécessite une gestion appropriée qui reconnaît les limites réelles de votre action immédiate face à cette personne restée hors de portée.", "perfect": "Je reste attentive à l''impossibilité matérielle d''établir un contact direct avec cette personne restée sur ce balcon, cette réalité limitant mon action immédiate.\n\nJe reste factuelle sur les suites possibles de cet outrage si l''identité de cette personne pouvait être établie, cette information restant utile pour une éventuelle procédure ultérieure.\n\nJe reste attentive à documenter les circonstances de ces propos, notamment l''horaire et le lieu précis, cette information restant utile pour la suite de cette situation.\n\nJe reste consciente que cette impossibilité de contact immédiat ne signifie pas une impunité totale, cette nuance restant importante pour ma propre gestion émotionnelle de cette situation.", "points": [{"position": 1, "label": "Rester attentive à l''impossibilité matérielle d''un contact direct", "weight": 2.0, "is_required": true, "kind": "core", "explanation_md": "Cœur du cas : réalité limitant l''action immédiate.", "groups": [{"position": 1, "keywords": ["contact impossible", "action limitée", "réalité reconnue"]}]}, {"position": 2, "label": "Rester factuelle sur les suites possibles si l''identité est établie", "weight": 1.5, "is_required": true, "kind": "core", "explanation_md": "Information utile pour une éventuelle procédure.", "groups": [{"position": 1, "keywords": ["suites possibles", "identité établie", "procédure envisagée"]}]}, {"position": 3, "label": "Documenter les circonstances de ces propos", "weight": 1.0, "is_required": true, "kind": "core", "explanation_md": "Horaire et lieu précis pour la suite de la situation.", "groups": [{"position": 1, "keywords": ["circonstances documentées", "horaire précisé", "lieu noté"]}]}, {"position": 4, "label": "Rester consciente que cette impossibilité ne signifie pas une impunité totale", "weight": 0.5, "is_required": false, "kind": "bonus", "explanation_md": "Nuance importante pour la gestion émotionnelle.", "groups": [{"position": 1, "keywords": ["impunité relativisée", "nuance maintenue", "gestion émotionnelle"]}]}]}, {"position": 3, "max_points": 5, "label": "Comment rendez-vous compte de cet outrage à votre hiérarchie une fois votre intervention terminée ?", "hint": "Ce compte rendu doit permettre de documenter cet outrage subi et d''envisager les suites appropriées, cette information restant importante pour la protection de votre équipage.", "perfect": "Je transmets à ma hiérarchie l''existence de cet outrage subi depuis ce balcon, cette information restant importante pour la protection de mon équipage face à ce type d''atteinte.\n\nJe reste factuelle sur les circonstances précises de ces propos, cette rigueur restant nécessaire pour un compte rendu fidèle de cette situation vécue.\n\nJe reste attentive à envisager avec ma hiérarchie l''opportunité d''un dépôt de plainte pour cet outrage, cette démarche restant possible malgré l''absence de contact direct avec l''auteur.\n\nJe reste disponible pour toute précision complémentaire, cette réactivité restant utile si une suite était donnée à cet incident constaté ce soir.", "points": [{"position": 1, "label": "Transmettre l''existence de cet outrage subi à la hiérarchie", "weight": 2.0, "is_required": true, "kind": "core", "explanation_md": "Cœur du cas : information importante pour la protection de l''équipage.", "groups": [{"position": 1, "keywords": ["outrage transmis", "équipage protégé", "hiérarchie informée"]}]}, {"position": 2, "label": "Rester factuelle sur les circonstances précises de ces propos", "weight": 1.5, "is_required": true, "kind": "core", "explanation_md": "Rigueur pour un compte rendu fidèle.", "groups": [{"position": 1, "keywords": ["circonstances précises", "compte rendu fidèle", "rigueur maintenue"]}]}, {"position": 3, "label": "Envisager avec la hiérarchie un dépôt de plainte pour cet outrage", "weight": 1.0, "is_required": true, "kind": "core", "explanation_md": "Démarche possible malgré l''absence de contact direct.", "groups": [{"position": 1, "keywords": ["plainte envisagée", "démarche possible", "outrage qualifié"]}]}, {"position": 4, "label": "Rester disponible pour toute précision complémentaire", "weight": 0.5, "is_required": false, "kind": "bonus", "explanation_md": "Réactivité utile pour une éventuelle suite.", "groups": [{"position": 1, "keywords": ["disponibilité maintenue", "précision complémentaire", "suite éventuelle"]}]}]}]}'::jsonb);
SELECT fn_cp_import_case('conflits-collegue-perd-son-calme', '{"slug": "conflits-collegue-perd-son-calme", "title": "Votre équipier hausse le ton et s''approche trop près", "theme_slug": "gestion-conflits", "difficulty": "difficile", "is_free": false, "is_published": true, "status": "published", "year": 2026, "month": "Juillet", "total_points": 15, "estimated_minutes": 30, "situation_text": "Il est 20 heures. Lors d''une intervention conjointe sur la voie publique, vous observez que votre équipier hausse le ton et s''approche de manière inappropriée d''une personne interpellée, cette perte de maîtrise de sa part se déroulant devant plusieurs personnes présentes qui observent cette scène, cette situation nécessitant une intervention de votre part directement sur le comportement de ce collègue plutôt que sur celui de la personne contrôlée. Cette configuration, où le problème provient de l''équipe elle-même et non de la personne interpellée, impose une gestion délicate qui reprenne la main sur cette intervention sans pour autant désavouer publiquement ce collègue devant ce public présent.\n\nCette situation, caractéristique des interventions où la difficulté ne provient pas de la personne contrôlée mais du comportement inapproprié d''un membre de votre propre équipage, nécessite une action rapide et mesurée pour ramener le calme sans humilier ce collègue devant les témoins de cette scène.\n\nCette configuration nécessite de reprendre la main sans désavouer publiquement ce collègue, cette double exigence restant essentielle pour rétablir un cadre professionnel tout en préservant la cohésion de votre équipage.", "questions": [{"position": 1, "max_points": 5, "label": "Comment reprenez-vous la main sur cette intervention sans désavouer publiquement ce collègue ?", "hint": "Cette reprise de main doit rester discrète et efficace, cette gestion évitant tout désaveu public de ce collègue devant les personnes présentes qui observent cette scène.", "perfect": "J''interviens rapidement pour ramener le calme dans cette situation, cette action restant nécessaire face à la perte de maîtrise manifestée par mon collègue devant ce public.\n\nJe reste attentive à formuler mon intervention de manière à ne pas désavouer publiquement ce collègue, cette discrétion restant essentielle pour préserver son autorité devant ces témoins.\n\nJe propose une intervention complémentaire plutôt qu''une contradiction frontale, cette approche restant préférable pour reprendre la main sans humilier mon équipier.\n\nJe reste attentive à créer une occasion de retrait pour ce collègue, cette solution restant appropriée pour lui permettre de reprendre ses esprits sans perte de face devant ce public.", "points": [{"position": 1, "label": "Intervenir rapidement pour ramener le calme dans cette situation", "weight": 2.0, "is_required": true, "kind": "core", "explanation_md": "Cœur du cas : action nécessaire face à la perte de maîtrise.", "groups": [{"position": 1, "keywords": ["calme ramené", "intervention rapide", "perte de maîtrise"]}]}, {"position": 2, "label": "Formuler son intervention sans désavouer publiquement ce collègue", "weight": 1.5, "is_required": true, "kind": "core", "explanation_md": "Discrétion préservant l''autorité devant les témoins.", "groups": [{"position": 1, "keywords": ["désaveu évité", "autorité préservée", "discrétion appliquée"]}]}, {"position": 3, "label": "Proposer une intervention complémentaire plutôt qu''une contradiction frontale", "weight": 1.0, "is_required": true, "kind": "core", "explanation_md": "Approche préférable pour reprendre la main sans humilier.", "groups": [{"position": 1, "keywords": ["intervention complémentaire", "contradiction évitée", "collègue préservé"]}]}, {"position": 4, "label": "Créer une occasion de retrait pour ce collègue", "weight": 0.5, "is_required": false, "kind": "bonus", "explanation_md": "Solution permettant de reprendre ses esprits sans perte de face.", "groups": [{"position": 1, "keywords": ["retrait proposé", "esprits repris", "perte de face évitée"]}]}]}, {"position": 2, "max_points": 5, "label": "Comment gérez-vous la personne interpellée face à ce comportement inapproprié de votre collègue ?", "hint": "Cette personne interpellée mérite une attention particulière compte tenu de ce comportement inapproprié qu''elle a subi de la part de votre collègue durant cette intervention.", "perfect": "Je reste attentive à l''état de cette personne interpellée face à ce comportement inapproprié de mon collègue, cette vigilance restant nécessaire pour évaluer l''impact de cette situation.\n\nJe reste factuelle et posée dans mes échanges avec cette personne, cette attitude restant utile pour rétablir un cadre professionnel malgré cet incident initial.\n\nJe reste attentive à ne pas minimiser ce qu''elle a pu ressentir face à ce comportement inapproprié, cette reconnaissance restant appropriée pour restaurer la confiance envers mon intervention.\n\nJe poursuis cette intervention de manière professionnelle, cette continuité restant nécessaire pour mener à bien cette procédure malgré cet incident survenu avec mon collègue.", "points": [{"position": 1, "label": "Rester attentive à l''état de cette personne face à ce comportement inapproprié", "weight": 2.0, "is_required": true, "kind": "core", "explanation_md": "Cœur du cas : vigilance sur l''impact de la situation.", "groups": [{"position": 1, "keywords": ["état surveillé", "impact évalué", "comportement inapproprié"]}]}, {"position": 2, "label": "Rester factuelle et posée dans les échanges avec cette personne", "weight": 1.5, "is_required": true, "kind": "core", "explanation_md": "Attitude rétablissant un cadre professionnel.", "groups": [{"position": 1, "keywords": ["échanges posés", "cadre professionnel", "attitude factuelle"]}]}, {"position": 3, "label": "Ne pas minimiser ce qu''elle a pu ressentir face à ce comportement", "weight": 1.0, "is_required": true, "kind": "core", "explanation_md": "Reconnaissance restaurant la confiance.", "groups": [{"position": 1, "keywords": ["ressenti reconnu", "confiance restaurée", "minimisation évitée"]}]}, {"position": 4, "label": "Poursuivre cette intervention de manière professionnelle", "weight": 0.5, "is_required": false, "kind": "bonus", "explanation_md": "Continuité malgré l''incident survenu.", "groups": [{"position": 1, "keywords": ["intervention poursuivie", "professionnalisme maintenu", "procédure menée"]}]}]}, {"position": 3, "max_points": 5, "label": "Comment abordez-vous ce sujet avec votre collègue une fois cette intervention terminée ?", "hint": "Cet échange avec votre collègue doit permettre d''aborder ce comportement inapproprié de manière constructive, cette discussion restant nécessaire pour éviter la reproduction de cette situation.", "perfect": "J''aborde ce sujet avec mon collègue en privé, cette discrétion restant essentielle pour ne pas l''exposer davantage après cet incident déjà vécu devant ce public.\n\nJe reste factuelle sur ce que j''ai observé de son comportement, cette description restant nécessaire pour qu''il prenne conscience de la perception qu''il a pu donner.\n\nJe reste à l''écoute des raisons qui ont pu expliquer cette perte de maîtrise, cette compréhension restant utile pour l''aider à mieux gérer ce type de situation à l''avenir.\n\nJe reste attentive à signaler si nécessaire cette situation à ma hiérarchie, cette transmission restant appropriée si ce comportement devait se reproduire ou paraître significatif.", "points": [{"position": 1, "label": "Aborder ce sujet avec ce collègue en privé", "weight": 2.0, "is_required": true, "kind": "core", "explanation_md": "Cœur du cas : discrétion évitant une exposition supplémentaire.", "groups": [{"position": 1, "keywords": ["discussion privée", "discrétion maintenue", "exposition évitée"]}]}, {"position": 2, "label": "Rester factuelle sur le comportement observé", "weight": 1.5, "is_required": true, "kind": "core", "explanation_md": "Description permettant une prise de conscience.", "groups": [{"position": 1, "keywords": ["comportement décrit", "prise de conscience", "description factuelle"]}]}, {"position": 3, "label": "Rester à l''écoute des raisons de cette perte de maîtrise", "weight": 1.0, "is_required": true, "kind": "core", "explanation_md": "Compréhension utile pour l''avenir.", "groups": [{"position": 1, "keywords": ["raisons écoutées", "compréhension recherchée", "avenir amélioré"]}]}, {"position": 4, "label": "Signaler si nécessaire cette situation à la hiérarchie", "weight": 0.5, "is_required": false, "kind": "bonus", "explanation_md": "Transmission appropriée en cas de reproduction.", "groups": [{"position": 1, "keywords": ["situation signalée", "hiérarchie informée", "reproduction évitée"]}]}]}]}'::jsonb);